<script setup lang="ts">
import { computed,onMounted,onUnmounted,reactive,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import { listManagedServers,type ManagedServer } from '../api/server-mgmt'
import { createInspection,deleteInspection,deleteInspectionPlan,downloadInspection,listInspectionPlans,listInspectionRuns,listOpsDatabases,saveInspectionPlan,type InspectionPlan,type InspectionRef,type InspectionRun,type OpsDatabase } from '../api/operations'
const route=useRoute(),router=useRouter(),tab=ref('runs'),runs=ref<InspectionRun[]>([]),plans=ref<InspectionPlan[]>([]),hosts=ref<ManagedServer[]>([]),databases=ref<OpsDatabase[]>([]),page=ref(1),total=ref(0),status=ref(''),error=ref(''),loading=ref(false),dialog=ref(false),saving=ref(false),mode=ref<'run'|'plan'>('run')
const form=reactive({id:0,name:'主机与数据库巡检',keys:[] as string[],services:'',enabled:true,dailyTime:'09:00',timezone:'Asia/Shanghai'})
const statusText=(s:string)=>({QUEUED:'等待下发',RUNNING:'执行中',COMPLETED:'已完成',PARTIAL:'部分完成',FAILED:'失败',CANCELED:'已取消',UNKNOWN:'待核实'}[s]||s)
const statusType=(s:string)=>s==='COMPLETED'?'success':s==='FAILED'?'danger':['PARTIAL','UNKNOWN'].includes(s)?'warning':'info'
const time=(s:string|null)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'-'
const options=computed(()=>[...hosts.value.map(h=>({key:`host:${h.id}`,label:`主机 · ${h.remark||h.host} · ${h.host}`})),...databases.value.map(d=>({key:`database:${d.id}`,label:`数据库 · ${d.name} · ${d.host}/${d.database}${d.serverId?'':'（未关联执行主机）'}`}))])
const refs=()=>form.keys.map(key=>({type:key.split(':')[0],id:Number(key.split(':')[1])} as InspectionRef))
async function load(){if(loading.value)return;loading.value=true;try{if(tab.value==='runs'){const r=await listInspectionRuns(page.value,20,status.value);runs.value=r.list;total.value=r.total}else plans.value=await listInspectionPlans();error.value=''}catch(e:any){error.value=e.message}finally{loading.value=false}}
function open(kind:'run'|'plan',plan?:InspectionPlan){mode.value=kind;Object.assign(form,{id:plan?.id||0,name:plan?.name||(kind==='run'?'主机与数据库巡检':'每日巡检'),keys:plan?(JSON.parse(plan.targetsJSON)||[]).map((t:InspectionRef)=>`${t.type}:${t.id}`):[],services:plan?(JSON.parse(plan.servicesJSON)||[]).join(','):'',enabled:plan?.enabled??true,dailyTime:plan?.dailyTime||'09:00',timezone:plan?.timezone||'Asia/Shanghai'});if(!plan&&route.query.host)form.keys=[`host:${route.query.host}`];dialog.value=true}
async function submit(){if(!form.keys.length){ElMessage.warning('请选择巡检对象');return};saving.value=true;try{const services=form.services.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean);if(mode.value==='run'){const r=await createInspection(form.name,refs(),services);dialog.value=false;router.push(`/inspections/${r.id}`)}else{await saveInspectionPlan({id:form.id||undefined,name:form.name,targets:refs(),services,enabled:form.enabled,dailyTime:form.dailyTime,timezone:form.timezone});dialog.value=false;await load();ElMessage.success('定时计划已保存')}}finally{saving.value=false}}
async function removeRun(row:InspectionRun){await ElMessageBox.confirm('删除此巡检及平台上的报告？此操作不修改被巡检服务器的业务数据。','删除巡检记录',{type:'warning'});await deleteInspection(row.id);await load()}
async function removePlan(row:InspectionPlan){await ElMessageBox.confirm('删除此定时计划？历史报告继续保留。','删除计划',{type:'warning'});await deleteInspectionPlan(row.id);await load()}
async function runPlan(row:InspectionPlan){const run=await createInspection(row.name,JSON.parse(row.targetsJSON),JSON.parse(row.servicesJSON)||[]);router.push(`/inspections/${run.id}`)}
async function report(id:number,format:'html'|'pdf'){try{await downloadInspection(id,format)}catch(e:any){ElMessage.error(e.message)}}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{[hosts.value,databases.value]=await Promise.all([listManagedServers(),listOpsDatabases()]);await load();if(route.query.host)open('run');timer=setInterval(load,5000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template><div class="inspections"><div class="heading"><div><h3>巡检中心</h3><p>下发只读执行包到指定主机，回收检查结果并生成 HTML／PDF 报告</p></div><div><el-button @click="open('plan')">新增定时计划</el-button><el-button type="primary" @click="open('run')">新建巡检任务</el-button></div></div><el-alert v-if="error" type="error" :title="error" :closable="false"/><div class="content"><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="巡检任务与报告" name="runs"/><el-tab-pane label="定时计划" name="plans"/></el-tabs>
<template v-if="tab==='runs'"><div class="filter"><el-select v-model="status" placeholder="全部状态" clearable style="width:160px" @change="page=1;load()"><el-option v-for="s in ['QUEUED','RUNNING','COMPLETED','PARTIAL','CANCELED']" :key="s" :value="s" :label="statusText(s)"/></el-select><el-button @click="load">刷新</el-button></div><el-table :data="runs" v-loading="loading" size="small"><el-table-column prop="id" label="#" width="65"/><el-table-column label="任务名称" min-width="200"><template #default="{row}"><el-link type="primary" @click="router.push(`/inspections/${row.id}`)">{{row.name}}</el-link></template></el-table-column><el-table-column label="执行状态" width="110"><template #default="{row}"><el-tag :type="statusType(row.status)" size="small">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="目标进度" width="100"><template #default="{row}">{{row.completedTargets}} / {{row.totalTargets}}</template></el-table-column><el-table-column label="检查结果" min-width="160"><template #default="{row}">告警 {{row.warningCount}} · 严重 {{row.criticalCount}} · 未知 {{row.errorCount}}</template></el-table-column><el-table-column prop="operator" label="发起人" width="110"/><el-table-column label="创建时间" width="175"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column><el-table-column label="报告" width="135"><template #default="{row}"><el-button text size="small" :disabled="row.htmlStatus!=='READY'" @click="report(row.id,'html')">HTML</el-button><el-button text size="small" :disabled="row.pdfStatus!=='READY'" @click="report(row.id,'pdf')">PDF</el-button></template></el-table-column><el-table-column width="65"><template #default="{row}"><el-button v-if="!['QUEUED','RUNNING'].includes(row.status)" text type="danger" size="small" @click="removeRun(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></template>
<template v-else><el-table :data="plans" v-loading="loading" size="small"><el-table-column prop="name" label="计划名称" min-width="200"/><el-table-column label="启用" width="85"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="执行时间" width="200"><template #default="{row}">每天 {{row.dailyTime}} · {{row.timezone}}</template></el-table-column><el-table-column label="下次执行" min-width="180"><template #default="{row}">{{time(row.nextRunAt)}}</template></el-table-column><el-table-column prop="lastError" label="最近调度提示" min-width="180" show-overflow-tooltip/><el-table-column label="对象数量" width="100"><template #default="{row}">{{JSON.parse(row.targetsJSON)?.length||0}}</template></el-table-column><el-table-column width="220"><template #default="{row}"><el-button text type="primary" @click="runPlan(row)">立即执行</el-button><el-button text @click="open('plan',row)">编辑</el-button><el-button text type="danger" @click="removePlan(row)">删除</el-button></template></el-table-column></el-table></template></div>
<div class="templates"><div><strong>Linux 主机模板</strong><p>系统信息、CPU、内存、磁盘空间、inode、网络和可选服务状态。CPU 指标为本次约 1 秒采样。</p></div><div><strong>PostgreSQL 模板</strong><p>实例身份、锁等待、当前慢 SQL、长事务、累计死锁及平台已采集的近 24 小时日志样本。权限不足和未接入日志单独列出。</p></div></div>
<el-dialog v-model="dialog" :title="mode==='run'?'新建巡检任务':form.id?'编辑定时计划':'新增定时计划'" width="720px"><el-form label-width="110px"><el-form-item label="名称"><el-input v-model="form.name" maxlength="128"/></el-form-item><el-form-item label="巡检对象"><el-select v-model="form.keys" multiple filterable placeholder="选择主机和数据库，可混合选择" style="width:100%"><el-option v-for="o in options" :key="o.key" :value="o.key" :label="o.label"/></el-select></el-form-item><el-form-item label="服务检查"><el-input v-model="form.services" type="textarea" :rows="2" placeholder="可选，仅主机模板使用。如：dfops,nginx,kubelet,containerd"/></el-form-item><template v-if="mode==='plan'"><el-form-item label="每天执行时间"><el-time-select v-model="form.dailyTime" start="00:00" step="00:15" end="23:45"/></el-form-item><el-form-item label="时区"><el-input v-model="form.timezone"/></el-form-item><el-form-item label="启用计划"><el-switch v-model="form.enabled"/></el-form-item></template><el-alert title="任务在登记的执行主机上运行，数据库对象需要先关联执行主机。报告生成失败可独立重试，已采集结果保持可追溯。" type="info" :closable="false"/></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">{{mode==='run'?'下发巡检任务':'保存计划'}}</el-button></template></el-dialog></div></template>
<style scoped>.inspections{display:flex;flex-direction:column;gap:16px}.heading{display:flex;justify-content:space-between;align-items:center}.heading h3{margin:0}.heading p{font-size:12px;color:#78899c;margin-bottom:0}.content{padding:14px 18px;background:#fff;border:1px solid #e2e8f0;border-radius:8px}.filter{display:flex;gap:12px;margin-bottom:15px}.el-pagination{justify-content:flex-end;margin-top:15px}.templates{display:grid;grid-template-columns:1fr 1fr;gap:16px}.templates>div{padding:18px;background:#f6f8fc;border:1px solid #e2e8f0;border-radius:7px}.templates strong{font-size:13px;color:#354d6d}.templates p{font-size:12px;color:#718198;line-height:1.8;margin-bottom:0}@media(max-width:950px){.heading{align-items:flex-start;gap:12px;flex-direction:column}.templates{grid-template-columns:1fr}}</style>
